"use strict";

// The NEGATIVE control that makes RWF-019 sound rather than merely
// conservative. It carries the identical always-throwing call in the two
// positions that are genuinely NOT class-definition time, and its later
// export must therefore REMAIN authoritative:
//
//  1. `ready = bail()` -- a non-computed INSTANCE FIELD VALUE, which is
//     installed by class evaluation and executed per-instance during
//     construction. This is RWF-018's line, and RWF-019 must not move it:
//     the very same element's computed KEY does run at definition time,
//     and conflating the two would withdraw authority from an export that
//     really is reached.
//  2. a computed key on a class DEFINED INSIDE a function that nothing
//     calls at module scope -- deferred until `configure()` runs, which it
//     never does here.
//
// Both are proven in-process in the ground-truth fixture's `c.js`.
function dangerousOp(input) {
  return "danger:" + input;
}

function safeOp(input) {
  return "safe:" + input;
}

function bail() {
  throw new Error("throws only on construction, or when configure() runs");
}

function configure() {
  class Deferred {
    [bail()] = 1;
  }
  return Deferred;
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  class Installed {
    ready = bail();
    lazy() {
      return bail();
    }
  }
}

safeOp.configure = configure;
module.exports = safeOp;
